import{_ as e,c as r,o,ah as s}from"./chunks/framework.RCw5T9E9.js";const p=JSON.parse('{"title":"Working with logs","description":"","frontmatter":{"title":"Working with logs"},"headers":[],"relativePath":"logs/general.md","filePath":"logs/general.md"}'),n={name:"logs/general.md"};function a(d,t,g,i,h,l){return o(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="working-with-logs" tabindex="-1">Working with logs <a class="header-anchor" href="#working-with-logs" aria-label="Permalink to &quot;Working with logs&quot;">​</a></h1><p>The <strong>Logs</strong> tab is a single chronological journal of what happens on the page: network requests, component props and emits, <strong>Pinia</strong> changes and actions, SPA navigation and JS errors. It helps to reconstruct a scenario step by step and to hand it over as a file.</p><p>The tab is always visible, comes after <strong>Pinia Store</strong>, and records events the same way in the extension and in <strong>Bookmark</strong> (<a href="/qa-tools/docs/standalone.html">Standalone</a>) mode.</p><h2 id="event-types" tabindex="-1">Event types <a class="header-anchor" href="#event-types" aria-label="Permalink to &quot;Event types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>What is logged</th></tr></thead><tbody><tr><td><strong>Send request</strong></td><td>Outgoing <strong>fetch</strong> / <strong>XMLHttpRequest</strong> call: URL, method, initiator, <strong>Params</strong>, request <strong>Headers</strong>, <strong>Authorization</strong>, request <strong>Body</strong></td></tr><tr><td><strong>Receive response</strong></td><td>Response to that call: status, duration, size, response <strong>Headers</strong>, response <strong>Body</strong>, network error</td></tr><tr><td><strong>Change props</strong></td><td>Changed props of a component: list of changes and full <strong>Before</strong> / <strong>After</strong> snapshots</td></tr><tr><td><strong>Emit</strong></td><td>Component event: component, event name, arguments, listener type (<strong>regular</strong> / <strong>once</strong>), parent chain</td></tr><tr><td><strong>Change store</strong></td><td>Changed <strong>Pinia</strong> state: list of changes and full <strong>Before</strong> / <strong>After</strong> snapshots. The type also includes the store&#39;s base states: <strong>Store initialized</strong>, <strong>Store snapshot</strong> and <strong>Store checkpoint</strong> (see <a href="#how-events-are-stored">How events are stored</a>)</td></tr><tr><td><strong>Store action</strong></td><td><strong>Pinia</strong> action call: arguments, result or error, status, duration</td></tr><tr><td><strong>Navigation</strong></td><td>SPA navigation: <strong>pushState</strong>, <strong>replaceState</strong>, <strong>popstate</strong>, <strong>hashchange</strong> with <strong>From</strong> / <strong>To</strong></td></tr><tr><td><strong>JS error</strong></td><td>Uncaught error, unhandled promise rejection or <code>console.error</code> of the page: message, source, location, compact stack (see <a href="#js-errors">JS errors</a>)</td></tr></tbody></table><p>Each network call produces <strong>two</strong> events that share one network entry. <strong>Send request</strong> shows what was sent, <strong>Receive response</strong> shows what came back. After a request is edited at a <a href="/qa-tools/docs/network/traffic.html">Breakpoint</a>, both events show the data that was actually sent and received.</p><h2 id="top-toolbar" tabindex="-1">Top toolbar <a class="header-anchor" href="#top-toolbar" aria-label="Permalink to &quot;Top toolbar&quot;">​</a></h2><h3 id="search" tabindex="-1">Search <a class="header-anchor" href="#search" aria-label="Permalink to &quot;Search&quot;">​</a></h3><p>The search box filters the table. The active criteria are set in <strong>Options → Logs → Search Settings</strong> (see <a href="./settings.html">Logs settings</a>):</p><table tabindex="0"><thead><tr><th>Mode</th><th>Description</th></tr></thead><tbody><tr><td><strong>By event name</strong></td><td>Title, component, store, URL</td></tr><tr><td><strong>By key</strong></td><td>Keys in the payload and changed paths</td></tr><tr><td><strong>By value</strong></td><td>Values in the payload</td></tr></tbody></table><p>For <strong>Change store</strong> and <strong>Change props</strong>, key and value search looks at the changed paths and values; full states are searched in the <strong>Store initialized</strong>, <strong>Store snapshot</strong> and <strong>Store checkpoint</strong> events.</p><p>As in other tabs, a query <strong>without</strong> quotes matches a substring, a query wrapped in <strong>double quotes</strong> <code>&quot;...&quot;</code> matches exactly. The minimum query length comes from the inspector search settings (default <strong>2</strong> characters).</p><h3 id="type" tabindex="-1">Type <a class="header-anchor" href="#type" aria-label="Permalink to &quot;Type&quot;">​</a></h3><p><strong>Type</strong> limits the table to the selected event types. All types are enabled by default. If every type is turned off, the table is empty and shows a hint to enable types again.</p><h3 id="status-indicators" tabindex="-1">Status indicators <a class="header-anchor" href="#status-indicators" aria-label="Permalink to &quot;Status indicators&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>N</strong> or <strong>N/M</strong></td><td>Rows after filters; with an active search or <strong>Type</strong> filter, <strong>M</strong> is the total number of events in the buffer</td></tr><tr><td><strong>ignored</strong></td><td>Number of ignored event groups. Click opens <strong>Ignored events</strong>: remove a single rule or <strong>Clear all</strong></td></tr><tr><td><strong>Paused</strong></td><td>Recording of new events is paused</td></tr></tbody></table><h3 id="log-controls" tabindex="-1">Log controls <a class="header-anchor" href="#log-controls" aria-label="Permalink to &quot;Log controls&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Control</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Pause</strong> / <strong>Resume</strong></td><td>Stop and resume recording new events</td></tr><tr><td><strong>Clear</strong></td><td>Remove all recorded events</td></tr><tr><td><strong>Export Logs</strong></td><td>Export events to an <strong>HTML</strong> report (see <a href="./export.html">Export</a>)</td></tr></tbody></table><h2 id="work-area" tabindex="-1">Work area <a class="header-anchor" href="#work-area" aria-label="Permalink to &quot;Work area&quot;">​</a></h2><h3 id="events-table" tabindex="-1">Events table <a class="header-anchor" href="#events-table" aria-label="Permalink to &quot;Events table&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Content</th></tr></thead><tbody><tr><td>Checkbox</td><td>Selection for export</td></tr><tr><td><strong>Time</strong></td><td>Event time with milliseconds</td></tr><tr><td><strong>Type</strong></td><td>Colored type badge</td></tr><tr><td><strong>Event</strong></td><td>Title and short description (method and path, component and event, store and changed keys, etc.)</td></tr></tbody></table><p>Rows are highlighted by level: <strong>4xx</strong> responses — warning; <strong>5xx</strong>, network errors, failed actions and JS errors — error.</p><h3 id="selection-for-export" tabindex="-1">Selection for export <a class="header-anchor" href="#selection-for-export" aria-label="Permalink to &quot;Selection for export&quot;">​</a></h3><p>The first column contains checkboxes, in the same position as the favorites star in <strong>Props</strong> and <strong>Pinia</strong>.</p><table tabindex="0"><thead><tr><th>Action</th><th>Result</th></tr></thead><tbody><tr><td>Click a checkbox</td><td>Select / unselect a row</td></tr><tr><td><strong>Shift</strong> + click</td><td>Select a range from the last clicked row</td></tr><tr><td><strong>Ctrl / Cmd</strong> + click on a row</td><td>Toggle a row without opening details</td></tr><tr><td><strong>Ctrl / Cmd</strong> + <strong>A</strong> (table focused)</td><td>Select all filtered rows</td></tr><tr><td>Header checkbox</td><td>Select all / clear selection</td></tr></tbody></table><p>When rows are selected, the button shows <strong>Export Logs (n)</strong> and exports only them. Without a selection, all filtered events are exported.</p><h3 id="event-details" tabindex="-1">Event details <a class="header-anchor" href="#event-details" aria-label="Permalink to &quot;Event details&quot;">​</a></h3><p>Clicking a row opens details on the right. The layout follows <strong>Network</strong>: a tab strip, name/value tables and <strong>JSON</strong> blocks in the selected <a href="/qa-tools/docs/options/json_mode.html">JSON mode</a>.</p><table tabindex="0"><thead><tr><th>Type</th><th>Tabs</th></tr></thead><tbody><tr><td><strong>Send request</strong></td><td><strong>Overview</strong>, <strong>Params (n)</strong>, <strong>Headers</strong>, <strong>Body</strong>, <strong>Raw</strong></td></tr><tr><td><strong>Receive response</strong></td><td><strong>Overview</strong>, <strong>Headers</strong>, <strong>Body</strong>, <strong>Raw</strong></td></tr><tr><td><strong>Change props</strong>, <strong>Change store</strong></td><td><strong>Changes (n)</strong>, <strong>Before</strong>, <strong>After</strong>, <strong>Raw</strong></td></tr><tr><td><strong>Store initialized</strong>, <strong>Store snapshot</strong>, <strong>Store checkpoint</strong></td><td><strong>Overview</strong>, <strong>State</strong>, <strong>Raw</strong></td></tr><tr><td><strong>Store action</strong></td><td><strong>Overview</strong>, <strong>Arguments</strong>, <strong>Result</strong> / <strong>Error</strong>, <strong>Raw</strong></td></tr><tr><td><strong>Emit</strong></td><td><strong>Arguments (n)</strong>, <strong>Overview</strong>, <strong>Raw</strong></td></tr><tr><td><strong>Navigation</strong>, <strong>JS error</strong></td><td><strong>Overview</strong>, <strong>Stack</strong> (errors), <strong>Raw</strong></td></tr></tbody></table><p><strong>Changes</strong> shows a diff by path: added, removed and changed values with the old and new value. Very large diffs are truncated; the full state stays available on <strong>Before</strong> / <strong>After</strong>.</p><p><strong>Before</strong> / <strong>After</strong> of a store change are restored from the store&#39;s base state and the changes after it. When that is impossible (the earlier events of the store are no longer in the log), the tab says so and <strong>Changes</strong> still shows the changed values; a value that cannot be restored is shown as <em>not available</em>.</p><p><strong>Raw</strong> shows the event with all restored fields.</p><p>If a network body was larger than the configured event size, <strong>Body</strong> shows a notice with the original size.</p><h3 id="event-actions" tabindex="-1">Event actions <a class="header-anchor" href="#event-actions" aria-label="Permalink to &quot;Event actions&quot;">​</a></h3><p>Actions are available in the <strong>⋮</strong> menu of the details header and in the row context menu (right click or <strong>⋮</strong> in the row):</p><table tabindex="0"><thead><tr><th>Action</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Export event</strong></td><td>Export one event. For network events the item is <strong>Export request &amp; response</strong>: both events of the request go into one file</td></tr><tr><td><strong>Copy cURL</strong></td><td>Copy the request as a cURL command (also available on <strong>Receive response</strong>: both events share the request data)</td></tr><tr><td><strong>Open request event</strong> / <strong>Open response event</strong></td><td>Jump to the paired network event</td></tr><tr><td><strong>Ignore</strong></td><td>Stop logging this group of events</td></tr></tbody></table><p><strong>Ignore</strong> works per group: the same request (method and path), the same component, the same store, and so on. Ignored groups are not recorded at all; they can be logged again from <strong>Options → Logs → Ignore list</strong>.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><h3 id="when-recording-starts" tabindex="-1">When recording starts <a class="header-anchor" href="#when-recording-starts" aria-label="Permalink to &quot;When recording starts&quot;">​</a></h3><p>Recording starts together with the rest of Vue Inspector in the tab context. Events are kept in the page, so the history is available when <strong>Logs</strong> is opened later, without reloading the page.</p><h3 id="how-events-are-stored" tabindex="-1">How events are stored <a class="header-anchor" href="#how-events-are-stored" aria-label="Permalink to &quot;How events are stored {#how-events-are-stored}&quot;">​</a></h3><p>Events keep only primary data; titles, descriptions and full states are derived when an event is shown.</p><ul><li><strong>Pinia.</strong> When a store is created while logging is running, a <strong>Store initialized</strong> event records its full state. When logging starts on a store that already exists, a <strong>Store snapshot</strong> event records its current state. After that, every <strong>Change store</strong> event stores only the changes. <strong>Before</strong> / <strong>After</strong> are rebuilt from the base state and the changes up to the event. Switching Inspector tabs does not create new snapshots. A new snapshot is recorded after <strong>Clear</strong> and after masking settings change. A recorded state is split like on the <strong>Pinia Store</strong> tab: <code>state</code> holds the declared state, <code>getters</code> holds getters and data the store keeps outside its declared state (for example, fields assigned in actions of an options store with an empty <code>state()</code>). Changes of both are tracked, so change paths start with <code>state.</code> or <code>getters.</code>.</li><li><strong>Network.</strong> <strong>Send request</strong> and <strong>Receive response</strong> reference one shared network entry. Equal response or request bodies (for example, a polled endpoint) are stored once.</li><li><strong>Shared snapshots.</strong> Identical values inside any event — props, store state, action arguments and results, emit arguments, errors, navigation — are stored once. Each later copy is a reference to that snapshot. The Logs tab and the HTML report restore the full value, so the data you see is the data that was captured.</li></ul><h3 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h3><p>A shared memory budget keeps long sessions stable: when it is reached, the oldest events are dropped. Events are kept whole by default; a maximum event size can be switched on. Groups of events can be switched off completely. Defaults and settings are described in <a href="./settings.html">Logs settings</a>.</p><p>Old <strong>Change store</strong> events are not simply dropped: they are compacted into a <strong>Store checkpoint</strong> with the store state at that point, so the history becomes <em>initial state → checkpoint → recent changes</em>. The initial state is kept, every remaining change can still be restored, and the compacted changes are no longer listed one by one (the checkpoint shows how many were compacted).</p><h3 id="js-errors" tabindex="-1">JS errors <a class="header-anchor" href="#js-errors" aria-label="Permalink to &quot;JS errors {#js-errors}&quot;">​</a></h3><p><strong>JS error</strong> events come from three sources, shown in <strong>Overview</strong> as <strong>Source</strong>: <strong>Uncaught error</strong>, <strong>Unhandled rejection</strong> and <strong>console.error</strong>.</p><ul><li><strong>Only the inspected page.</strong> Whether an error is the page&#39;s is decided by where it comes from (the caller in the stack), not by its text. Messages and errors of Vue Inspector itself and of other browser extensions are not logged. This includes Vue Inspector&#39;s internal reports about failed <strong>fetch</strong> / <strong>XHR</strong> requests: such a request is already a <strong>Network</strong> event. The app&#39;s own <code>console.error</code> about a failed request is kept.</li><li><strong>console.error.</strong> The message is built like in the browser console (<code>%s</code>, <code>%d</code>, <code>%o</code> and similar are applied, objects are shown as a short preview); object arguments are kept in <strong>Raw</strong>. <strong>Location</strong> points to the line of the app that called <code>console.error</code>, or to the top frame of an error passed to it. More than 50 messages per second are not logged; the next event shows how many were skipped (<strong>Suppressed</strong>).</li><li><strong>Compact stack.</strong> The message and the top 10 frames are kept — that is where the error happened. A cut stack ends with <em>… N more frames (stack truncated)</em>, and <strong>Overview</strong> shows <strong>Stack: Truncated</strong> with the number of kept frames.</li><li><strong>WebSocket</strong> messages are not captured.</li></ul><p>Errors of the inspected page stay in the page console and in <strong>Logs</strong>. They are not added to the extension error list (<code>chrome://extensions</code>); that list shows only failures of Vue Inspector itself. While logging runs, a page <code>console.error</code> passes through a small page-side bridge, so the browser console may attribute that line to the bridge. The message and the stack are unchanged.</p><h3 id="data-masking" tabindex="-1">Data masking <a class="header-anchor" href="#data-masking" aria-label="Permalink to &quot;Data masking&quot;">​</a></h3><p>Sensitive data is masked <strong>when an event is captured</strong>, so it never reaches the view or exports: passwords, tokens, cookies, authorization headers, card numbers and similar keys, as well as <strong>JWT</strong>, <strong>Bearer</strong> / <strong>Basic</strong> credentials and card numbers inside any text.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./export.html">Export</a></li><li><a href="./settings.html">Logs settings</a></li><li><a href="/qa-tools/docs/network/general.html">Working with requests</a></li></ul>',54)])])}const u=e(n,[["render",a]]);export{p as __pageData,u as default};
